import uuid
def parse_resource_id(value):
    if not isinstance(value,str) or not value.startswith('/') or value.endswith('/') or any(ch.isspace() for ch in value) or '?' in value or '#' in value:raise ValueError('resource-group resource ID')
    parts=value[1:].split('/')
    if len(parts)<8 or len(parts)%2 or any(not x for x in parts) or [parts[i].lower() for i in (0,2,4)]!=['subscriptions','resourcegroups','providers'] or any(x.lower()=='providers' for x in parts[6:]):raise ValueError('one provider and type/name pairs')
    try:subscription=str(uuid.UUID(parts[1]))
    except (ValueError,AttributeError):raise ValueError('subscription UUID')
    return {'subscription':subscription,'resource_group':parts[3],'provider':parts[5],'types':parts[6::2],'names':parts[7::2]}
