import fnmatch
def allows(roles,operation,plane):
    if plane not in ('management','data'):raise ValueError('explicit plane')
    include,exclude=('actions','notActions') if plane=='management' else ('dataActions','notDataActions')
    grants=[]
    for role in roles:
        for permission in role['permissions']:
            if set(permission)-{'actions','notActions','dataActions','notDataActions'}:raise ValueError('finite role permission block')
            for key,patterns in permission.items():
                if not isinstance(patterns,list) or any(not isinstance(x,str) or any(ch in x for ch in '[]?') for x in patterns):raise ValueError('finite star patterns')
            matched=any(fnmatch.fnmatchcase(operation.lower(),pattern.lower()) for pattern in permission.get(include,[]))
            removed=any(fnmatch.fnmatchcase(operation.lower(),pattern.lower()) for pattern in permission.get(exclude,[]))
            grants.append(matched and not removed)
    return any(grants)
```

