def lock_gate(locks,resource,method,plane):
    if plane not in ('management','data') or method not in ('GET','HEAD','POST','PUT','PATCH','DELETE'):raise ValueError('finite method/plane')
    blocked=[];target=resource.casefold().rstrip('/')
    for lock in locks:
        scope=lock['scope'].casefold().rstrip('/')
        if lock['level'] not in ('CanNotDelete','ReadOnly'):raise ValueError('lock level')
        if plane=='data' or not(target==scope or target.startswith(scope+'/')):continue
        if lock['level']=='ReadOnly' and method not in ('GET','HEAD') or lock['level']=='CanNotDelete' and method=='DELETE':blocked.append(lock['id'])
    return {'allowed_by_locks':not blocked,'blocking_locks':sorted(set(blocked))}
```

